u16 sega_logo_cram[64];
static s16 cyc_cnt;        /* $F632 */
static s16 cyc_timer;      /* $F634 (byte) */
static u16 cyc_phase2;     /* $F635 */

void sega_logo_draw(u16 vramBase)
{
    VDP_loadTileData(sega_logo_tiles, vramBase, SEGA_LOGO_TILE_COUNT, DMA);
    /* plane B first (behind A): letter color cells at tile (8,10) */
    for (u16 ty = 0; ty < 8; ty++)
        for (u16 tx = 0; tx < 24; tx++) {
            u16 w = sega_logo_map_b[ty * 24 + tx];
            VDP_setTileMapXY(BG_B, (w & 0xF800) | ((w & 0x7FF) + vramBase),
                             8 + tx, 10 + ty);
        }
    /* plane A: white card with letter-shaped holes + TM */
    for (u16 ty = 0; ty < 28; ty++)
        for (u16 tx = 0; tx < 40; tx++) {
            u16 w = sega_logo_map_a[ty * 40 + tx];
            VDP_setTileMapXY(BG_A, (w & 0xF800) | ((w & 0x7FF) + vramBase),
                             tx, ty);
        }
}

void sega_palcycle_reset(void)
{
    for (u16 i = 0; i < 64; i++) sega_logo_cram[i] = 0x0EEE;
    cyc_cnt = -10; cyc_timer = 0; cyc_phase2 = 0;
}

u16 sega_palcycle_step(void)
{
    if (!cyc_phase2) {
        /* phase 1: shimmer band sweeps the letter columns (CRAM 16..63,
         * skipping each line's color 0) */
        s16 d0 = cyc_cnt;
        u16 ti = 0, n = 6;
        while (d0 < 0) { ti++; n--; d0 += 2; }
        for (u16 k = 0; k < n; k++) {
            if ((d0 & 0x1E) == 0) d0 += 2;
            if (d0 < 0x60) sega_logo_cram[16 + (d0 >> 1)] = band_tbl[ti + k];
            d0 += 2;
        }
        d0 = cyc_cnt + 2;
        if ((d0 & 0x1E) == 0) d0 += 2;
        if (d0 >= 0x64) { cyc_timer = 4; cyc_phase2 = 1; d0 = -12; }
        cyc_cnt = d0;
        return 1;
    }
    /* phase 2: every 5th frame, one of 4 settle steps (white -> blue) */
    cyc_timer--;
    if (cyc_timer >= 0) return 1;
    cyc_timer = 4;
    s16 d0 = cyc_cnt + 0x0C;
    if (d0 >= 0x30) return 0;
    cyc_cnt = d0;
    const u16 *row = &settle_tbl[d0 >> 1];
    for (u16 k = 0; k < 5; k++) sega_logo_cram[2 + k] = row[k];
    {
        u16 flood = row[5];
        d0 = 0;
        for (u16 i = 0; i < 45; i++) {
            if ((d0 & 0x1E) == 0) d0 += 2;
            sega_logo_cram[16 + (d0 >> 1)] = flood;
            d0 += 2;
        }
    }
    return 1;
}
